import { test } from 'node:test';
import assert from 'node:assert/strict';
import { collectCoin, createState } from '../src/logic/score.js';

test('collecting a coin counts it', () => {
  assert.equal(collectCoin(createState()).coins, 1);
});

test('a new game starts at zero score', () => {
  assert.equal(createState().score, 0);
});

test('each coin is worth 10 points', () => {
  assert.equal(collectCoin(createState()).score, 10);
});

test('points add up across coins', () => {
  const state = collectCoin(collectCoin(collectCoin(createState())));
  assert.deepEqual(state, { coins: 3, score: 30 });
});

test('collecting does not change the state it was given', () => {
  const before = createState();
  collectCoin(before);
  assert.deepEqual(before, { coins: 0, score: 0 });
});

